INSERT INTO public.categories (name, slug, description, icon, sort_order) VALUES
 ('Whiteboard Supplies','whiteboard-supplies','Markers, inks and dusters for classrooms, offices and boardrooms.','PenLine',1),
 ('Scientific Calculators','scientific-calculators','Genuine Casio scientific calculators for school, college and professional use.','Calculator',2),
 ('Mathematical Tables','mathematical-tables','KLB mathematical tables approved for Kenyan schools and national exams.','Table',3),
 ('Mathematical Sets','mathematical-sets','Geometry sets, set squares, drawing sets and gift sets.','Compass',4),
